INSERT INTO [game].[RoundAnswers] ([Id], [RoundId], [GamePlayerId], [AnswerType], [Text], [SubmittedAt]) VALUES
    ('cca0d133-0424-4245-9493-0cc07eef8508', '22cd141c-ea43-4369-a02c-fc5235d9ae9a', 'bfb7cc43-234f-408d-9713-7d9940925112', N'FACTUAL_REASONING', N'這件作品的外觀和同類器物有幾個共同點，但器底加工與尺寸比例仍值得再比對。我的判斷先停在合理範圍，不把一項紋飾直接當成唯一證據。', CONVERT(datetime2(3), '2026-08-29T08:12:25.1230000', 126)),
    ('cc65dcc1-8d29-4ca7-b56e-180740ab4b66', '7e038460-0d98-44e7-8238-9a0cc18248a1', '39500e1b-13f4-4860-8828-0fed4a1cc114', N'PLAUSIBLE_FICTION', N'從紋飾節奏與器物的視覺重量來看，它可能在陳設或儀式中扮演重要角色。若要讓這個推測更可靠，還是要補上尺寸、出處和同類作品的比較結果。', CONVERT(datetime2(3), '2026-08-23T08:09:25.1230000', 126)),
