INSERT INTO [social].[Events] ([Id], [EventType], [OrganizerUserId], [Title], [Content], [Location], [Latitude], [Longitude], [StartAt], [EndAt], [RegistrationEndAt], [Capacity], [ReviewStatus], [PublishStatus], [ReviewNote], [ReviewedByUserId], [ReviewedAt], [CreatedAt]) VALUES
    ('2298c774-f78d-41d4-bda4-8c869da33fa1', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'青銅器紋飾讀圖工作坊', N'本場從幾何紋、動物紋與器身轉折開始，帶著參加者練習把「看見的線條」和「對紋飾的推測」分開記錄。前半段會以完整影像建立觀看順序，後半段再放大器口、腹部與底部的局部，對照鑄造痕跡、構圖節奏與容易被光線掩蓋的細節。參加者不需要先熟悉專有名詞，只要帶著一個想查證的問題即可。', N'國立故宮博物院｜臺北市士林區至善路二段221號', 25.102400, 121.548500, CONVERT(datetime2(3), '2026-09-05T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-05T10:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-02T07:56:22.6770000', 126), 24, N'APPROVED', N'PUBLISHED', N'活動內容與報名資訊已確認。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-03T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-26T07:56:22.6770000', 126)),
    ('3f2bf0ea-aa9c-402c-96cf-cd308225b8dc', N'PLAYER', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'夜間文物猜謎會', N'活動會以局部圖像、簡短提示卡和分組討論進行三個回合；每回合先讓大家寫下看到的線索，再逐步開放材質、器形或來源提示。揭曉後不只公布答案，也會一起回看哪些判斷有圖鑑資料支持、哪些只是當下的直覺。適合想用輕鬆方式練習觀察，又願意把推理過程說出來的玩家。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', NULL, NULL, CONVERT(datetime2(3), '2026-09-25T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-25T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-22T07:56:22.6770000', 126), 30, N'PENDING', N'DRAFT', NULL, NULL, NULL, CONVERT(datetime2(3), '2026-09-15T07:56:22.6770000', 126)),
    ('ae880904-f729-4dff-8698-d3335f57776b', N'PLAYER', '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'玩家交流：我第一次看懂的細節', N'這是一場由玩家帶路的交流，大家可以分享自己在圖鑑裡第一次真正看懂的細節，也可以帶著曾經猜錯的作品來討論。流程會先用五分鐘說明作品名稱與資料來源，再交換辨識方法、查找過程和仍然沒有答案的問題；不要求每個人得出相同結論，重點是讓其他會員知道你的觀察從哪裡開始。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-18T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-18T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-16T07:56:22.6770000', 126), 16, N'APPROVED', N'PUBLISHED', N'符合玩家交流活動規範。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-16T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-08T07:56:22.6770000', 126)),
    ('59879d31-aa46-4839-b3e1-e8ed8023a44c', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'週末館藏導讀：從器形看年代', N'本次導讀挑選三件不同時期的器物，先從通高、口徑、腹部比例與器足觀察整體形制，再回到材質、紋飾和來源欄位交叉比對。講者會示範如何保留年代原文與不確定範圍，也會安排一段讓參加者把自己的第一印象改寫成可以回查的觀察筆記，適合第一次使用圖鑑或想練習慢慢看作品的參加者。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', 23.470900, 120.294100, CONVERT(datetime2(3), '2026-09-12T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-12T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-09T07:56:22.6770000', 126), 40, N'APPROVED', N'PUBLISHED', N'已完成場次與講者資料確認。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-10T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-02T07:56:22.6770000', 126)),
    ('8d293743-c9a1-4478-9611-f00eb65253b0', N'PLAYER', '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'玩家提案：我的地方文物小旅行', N'這個提案想從地方博物館、歷史建築與沿線街區開始，分享一條可以實際走訪的文物小旅行。發起人預計整理交通方式、開放時間、建議停留長度、照片來源與每一站想觀察的問題，也歡迎其他會員補充自己的路線。正式成團前會先確認活動流程、集合方式與可公開使用的資料來源。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-30T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-30T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-24T07:56:22.6770000', 126), 20, N'REJECTED', N'DRAFT', N'目前提案缺少明確的活動流程與資料來源，請補充後重新送審。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-28T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-20T07:56:22.6770000', 126)),
    ('be150dd2-6067-41be-8d99-f03a80a51964', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'古典色彩與保存觀察', N'本場會從常見顏料、釉色與表面保存狀態切入，帶領參加者比較色彩變化在辨識上的幫助與限制。除了看作品本身，也會討論拍攝光線、反光、修復痕跡和螢幕顯示可能造成的誤判，最後將一段過度肯定的描述改寫成保留證據範圍的觀察筆記。活動結束後可回到圖鑑繼續查找相關作品。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', 23.470900, 120.294100, CONVERT(datetime2(3), '2026-08-26T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-26T10:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-19T07:56:22.6770000', 126), 18, N'APPROVED', N'CANCELLED', N'因場地維護取消本場活動，後續將另行公告。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-08-24T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-16T07:56:22.6770000', 126)),
    ('b096b0a3-d410-4ad3-906a-f4f5f3c0b791', N'OFFICIAL', '4134ddc4-ca89-4180-ac72-bbe0f42ab285', N'小型器物的手感與比例', N'本場從鑑定遊戲裡常見的小型器物題目延伸，先讓參加者比較不同作品的通高、口徑、器壁厚薄與可想像的拿取方式，再討論「手感」哪些可以從資料推測、哪些必須保留為想像。活動會把遊戲作答、圖鑑欄位和個人筆記放在一起回顧，練習不要只用一個醒目的特徵替作品下結論。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-08T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-08T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-06T07:56:22.6770000', 126), 28, N'PENDING', N'DRAFT', NULL, NULL, NULL, CONVERT(datetime2(3), '2026-08-29T07:56:22.6770000', 126));
INSERT INTO [social].[SocialComments] ([Id], [PostId], [ParentCommentId], [UserId], [Content], [Status], [CreatedAt], [UpdatedAt]) VALUES
    ('f35df9b8-2851-2758-a59f-000fc471438f', 'e3179cdf-eb1f-af50-8dde-d371e9e7eb89', '6b09a231-b07b-8d5f-951a-4bfeb4033117', 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'我會把這回合最早注意到的線索和最後採用的理由都記下來，下一次遇到相近題型時比較能看出自己真正需要練習的是觀察還是時間分配。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-15T09:54:00.0000000', 126), CONVERT(datetime2(3), '2026-08-15T09:54:00.0000000', 126)),
    ('c8de76cc-38b8-b552-8ee9-0034f91538ab', '908f40ce-b5a7-b153-9b9f-d6f7ecbd5739', 'f25e4c59-7c2b-8f50-ac2b-76782c0ea852', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-02T08:41:00.0000000', 126), CONVERT(datetime2(3), '2026-08-02T08:41:00.0000000', 126)),
    ('a8c2cda6-fa37-235e-8312-0049f9945bdb', 'c9eacb60-647d-165d-a650-f15ba568c1da', '98a1046d-93fe-ff59-a770-db77382442f5', '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-17T00:44:00.0000000', 126), CONVERT(datetime2(3), '2026-01-17T00:44:00.0000000', 126)),
    ('51d6c03f-e602-d354-809e-00fe8088156a', 'da294627-14d1-7952-8da9-8ddc278a69de', 'b4f5a07a-648e-145e-aea3-39fe2d97c257', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-01T03:04:00.0000000', 126), CONVERT(datetime2(3), '2025-12-01T03:04:00.0000000', 126)),
    ('e9da6296-c8ed-9b56-a03c-019555c54128', '958c8440-1396-2f55-a591-2b2320924f6f', NULL, 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'我也很有共鳴，尤其是「一天只安排兩個展區，反而有空間把筆記寫完整」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-18T08:26:00.0000000', 126), CONVERT(datetime2(3), '2025-11-18T08:26:00.0000000', 126)),
    ('3985fb6e-07c7-bd5c-a0d5-02634ccf609d', '0e94d2cc-7e36-2053-8cd9-999e278026fb', NULL, 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-26T00:43:00.0000000', 126), CONVERT(datetime2(3), '2026-05-26T00:43:00.0000000', 126)),
    ('ccd91e9a-89eb-c255-8cdf-029d3731bb3c', 'd77ed3d0-ec84-1158-891a-04a0838c9c2e', 'd858cbfe-83dc-d254-9b50-8577977e588c', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-20T11:49:00.0000000', 126), CONVERT(datetime2(3), '2026-01-20T11:49:00.0000000', 126)),
    ('b03d6dbc-5a61-df5e-84f6-032dde3d202e', 'ac06a04a-27a8-d85d-9d5c-d8f0f01a6e25', '004799e8-365b-6050-a693-1aa4eaad87c7', '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-05T09:47:00.0000000', 126), CONVERT(datetime2(3), '2026-02-05T09:47:00.0000000', 126)),
    ('06ef8b2c-b4ae-265f-b20b-0367e5ff4eb4', 'cb31c93c-8d6c-2757-a688-5ed1e297af34', '12c8b08f-2134-5559-a7a2-244b965f0c37', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-25T09:42:00.0000000', 126), CONVERT(datetime2(3), '2026-07-25T09:42:00.0000000', 126)),
    ('797c7269-8015-4ebe-84c5-041ab997298a', '9ece1da9-d8d8-4ee8-a604-37111ad920dc', NULL, '59538e0b-3f85-46d0-93d6-cccb9df12831', N'這個主題很適合拿來做前後對照，我會先列出三個可以直接看見的差異，再查資料解釋原因。先有明確比較基準，討論時比較不會停留在感覺。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-30T19:25:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('ede01536-b2de-2d50-928b-048b8f0dfffb', 'ef0513a5-ea0f-d955-9d79-9474b8b79367', 'b7f53adb-d0a6-585f-b23e-946df5523ac3', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-12T10:34:00.0000000', 126), CONVERT(datetime2(3), '2025-10-12T10:34:00.0000000', 126)),
    ('2ac0b4cf-47b5-6755-af14-048c3e157933', '96690504-0727-675d-a2e0-ee0c0abc7495', NULL, 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'我也很有共鳴，尤其是「展場聲音和人流也會影響我對作品的第一印象」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-26T07:49:00.0000000', 126), CONVERT(datetime2(3), '2026-08-26T07:49:00.0000000', 126)),
    ('3f442e2b-21a5-5652-9787-04ae29539f29', '17327017-40a5-a95d-902d-9fae2b56af51', NULL, '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-28T08:47:00.0000000', 126), CONVERT(datetime2(3), '2026-07-28T08:47:00.0000000', 126)),
    ('9b9a21a5-801f-e358-ab62-04edc1cbaf80', 'ea125a61-0806-bd56-8278-38b022b8d139', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'我也很有共鳴，尤其是「如果作品只有一個角度的圖，大家會先怎麼避免過度解讀」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-29T11:30:00.0000000', 126), CONVERT(datetime2(3), '2026-06-29T11:30:00.0000000', 126)),
    ('a0bf2bad-043b-3c53-a955-04fa14c44b4a', 'fb85df44-71ce-3358-8c5c-70653b6443b9', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-14T02:57:00.0000000', 126), CONVERT(datetime2(3), '2026-04-14T02:57:00.0000000', 126)),
    ('2b7b86b2-89c0-4374-897e-0639bc3f20f5', '9146dd44-8fdc-45ad-85f1-7f1c34cee5e1', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'這個觀察也提醒我不要只依賴單一欄位。年代、分類與來源彼此可以互相校對，但任何一項都不應該脫離完整資料單獨決定答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T05:20:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('88d379ad-afa3-d353-ac3e-06491d604a16', '6e4bd3ab-6e5f-5b5c-974e-fde14ecd9735', NULL, 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'我剛好在另一件相近作品上遇到類似情況，表面看起來很像，但器底與尺寸比例其實差不少。這篇提供了一個很好的比較起點。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-24T02:27:00.0000000', 126), CONVERT(datetime2(3), '2026-04-24T02:27:00.0000000', 126)),
    ('47a4a511-1468-6851-8494-06b053cd9093', '94d48c6b-46b3-fc5f-9ff1-e1475252c442', '08a5f65c-da0a-4d51-a863-89cf443a4c72', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'若是第一次到場，我還會先確認入口、樓層和報到方式；這些細節不一定適合塞進標題，但對真正要參加的人很重要。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-09T07:14:00.0000000', 126), CONVERT(datetime2(3), '2025-10-09T07:14:00.0000000', 126)),
    ('c1d25c12-a260-d250-92ce-06c07265ed4f', '26ea876d-b1ed-e85a-b8e6-9d269cb40a58', '1520019b-dbef-c458-9df2-44914bee3b1f', '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-15T02:35:00.0000000', 126), CONVERT(datetime2(3), '2026-08-15T02:35:00.0000000', 126)),
    ('301d9124-79eb-df5f-b3d9-06c4f3992dcb', 'f6c34f0d-5545-6751-a235-22c138d3c113', '6152758b-2285-1a5d-959b-c11c7b6e150c', 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-28T11:00:00.0000000', 126), CONVERT(datetime2(3), '2025-11-28T11:00:00.0000000', 126)),
    ('95a3b2c5-41d1-e058-9503-07cc761e887a', '19852cde-895c-c65d-9d74-0215c96c67b2', '37602ab5-13de-a85a-a365-87e5a6647a4c', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-30T07:05:00.0000000', 126), CONVERT(datetime2(3), '2025-12-30T07:05:00.0000000', 126)),
    ('95705dd4-f275-385d-a062-082835037adb', '0abb32d3-a338-7153-87f3-efcc1b15db73', NULL, '32090e80-8d61-4801-b480-a6358f7a9e37', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-05T07:38:00.0000000', 126), CONVERT(datetime2(3), '2026-07-05T07:38:00.0000000', 126)),
    ('99e30063-5bf5-255e-bc29-0858a01c8927', '93eb8a2b-b90c-a25a-91c8-7efdfccea368', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'我也很有共鳴，尤其是「把參觀心得說給沒去過的人聽，才知道哪些背景真的需要補充」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-09-16T05:47:00.0000000', 126), CONVERT(datetime2(3), '2025-09-16T05:47:00.0000000', 126)),
    ('4d73efb3-ee04-7a5f-a242-08a9e83402a7', 'a516868f-b544-b95f-a620-a14626870609', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'我也會先看玉羊的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-10T00:25:00.0000000', 126), CONVERT(datetime2(3), '2026-05-10T00:25:00.0000000', 126)),
    ('f6a037f1-38c3-1c52-aad4-08c6824859fe', '035c641c-6eb0-8d58-a828-bf1a8f28a540', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'我也很有共鳴，尤其是「我現在會把遊戲結果當成回到圖鑑的入口，而不是最後答案」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-16T05:24:00.0000000', 126), CONVERT(datetime2(3), '2026-08-16T05:24:00.0000000', 126)),
    ('edf5a0d5-2071-46f4-8855-08fd76f99775', '8997e673-1c56-454e-9337-710678c22122', NULL, '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'讀到這段時我想到保存狀況也會影響判讀，尤其是顏色與光澤。把官方描述、照片條件和自己的觀察分開，之後修正筆記會方便很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T00:31:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('f07f937a-51dc-b455-ab48-091d78c7079c', '2391f330-6ee0-3e5b-872d-653180ed3782', 'f375326d-856f-b75b-9205-a4eeaddba3e5', '7881ef5d-547d-4d08-b71d-a48be2000a35', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-11T08:42:00.0000000', 126), CONVERT(datetime2(3), '2026-04-11T08:42:00.0000000', 126)),
    ('f9e4cef6-93f7-4b5a-9d86-0979b5804305', 'a331b6d4-cc7e-2b5d-abdb-5a26bd4f1775', NULL, 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'我也會先看熙寧元寶的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-23T08:46:00.0000000', 126), CONVERT(datetime2(3), '2025-11-23T08:46:00.0000000', 126)),
    ('43c6b6aa-8064-2058-a563-0b1663a74148', 'ac484caf-fd99-f95a-b7d5-aa0929a466f7', '0252595b-ba06-b950-a660-8bfbad75657d', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'如果前台之後提供更多互動，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-24T09:38:00.0000000', 126), CONVERT(datetime2(3), '2026-03-24T09:38:00.0000000', 126)),
    ('89f01341-d3e9-f65f-ba24-0b41d68ce24c', 'a875e167-b5b9-c459-a152-65e82d465121', '391c2288-64f1-bf56-8a03-d60a565512a7', 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-02T10:33:00.0000000', 126), CONVERT(datetime2(3), '2026-02-02T10:33:00.0000000', 126)),
    ('1c6b9347-a661-d859-adc2-0b942ddbd62a', '8a2d16b2-c536-175b-9d83-6e13919d3f1a', NULL, 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-16T05:36:00.0000000', 126), CONVERT(datetime2(3), '2026-06-16T05:36:00.0000000', 126)),
    ('4698a813-1c5a-a858-96e8-0c86800206ea', '5d2e7ea7-c9be-be5b-8399-12fe3fd31a5d', NULL, '7881ef5d-547d-4d08-b71d-a48be2000a35', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-15T09:47:00.0000000', 126), CONVERT(datetime2(3), '2025-11-15T09:47:00.0000000', 126)),
    ('77344c03-8150-6058-81a6-0cda5a415cca', '9e49ba45-d0fd-0c55-a3f0-7706dc2f8e3d', '412bbcdd-6f84-2e54-b816-3c79dcce8a02', 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-26T10:44:00.0000000', 126), CONVERT(datetime2(3), '2026-03-26T10:44:00.0000000', 126)),
    ('45321f41-7e18-2e53-9f59-0cf7544193cf', 'd0f8799f-9cd6-ab5e-a0c1-11edbd57f145', '88210352-0ca5-1652-a6c9-29a044872398', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-29T10:15:00.0000000', 126), CONVERT(datetime2(3), '2026-04-29T10:15:00.0000000', 126)),
    ('2990da4f-7fb5-1d5d-98e1-0d0ece2b248f', '47966729-b0f2-c95d-9a6f-2413f53842c8', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'讀完後我會想再找不同角度的影像來對照。牙雕鏤空描金白彩花卉紋梳這類作品如果只看縮圖，真的很容易漏掉邊緣與接合處的線索。', N'HIDDEN', CONVERT(datetime2(3), '2026-01-22T07:56:00.0000000', 126), CONVERT(datetime2(3), '2026-01-22T07:56:00.0000000', 126)),
    ('10125f6f-ef33-d555-8ff3-0d20541de964', '0a530476-33c3-0255-85d3-d726a414e1d7', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'我也很有共鳴，尤其是「活動中聽到的補充，我回家沒有直接當成最後定論」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-25T11:29:00.0000000', 126), CONVERT(datetime2(3), '2025-10-25T11:29:00.0000000', 126)),
    ('7289fdfc-91fc-305c-867f-0d4e9be119d6', 'ee2b1f16-3d7d-4e57-9dde-81d9b0c17564', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-29T04:55:00.0000000', 126), CONVERT(datetime2(3), '2026-06-29T04:55:00.0000000', 126)),
    ('d9496e81-c0d0-d650-9df6-0dfdce232c7f', '53ac137e-5e54-d55e-b3d7-93593a7094a7', NULL, '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-07T05:54:00.0000000', 126), CONVERT(datetime2(3), '2026-02-07T05:54:00.0000000', 126)),
    ('2a9aa2e5-6b78-c858-be43-0e7fbd727f9e', '6110e474-c87e-d353-9a3e-5f48621ae8bc', 'fcf90586-b36f-bc5d-9085-3d9dcf5d6e3e', '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-21T11:07:00.0000000', 126), CONVERT(datetime2(3), '2026-04-21T11:07:00.0000000', 126)),
    ('b4dc8806-d811-8355-abd8-0e85c73c953d', '00d36a2a-039f-ea5d-9de0-896df2a75b43', '180677ce-cc6a-1f5c-89b7-ff425b9400a7', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-22T01:08:00.0000000', 126), CONVERT(datetime2(3), '2025-10-22T01:08:00.0000000', 126)),
    ('e78942fa-f486-f253-8cc6-0e94700dc103', 'd235b0f5-b447-9f5e-9a23-10b5a7b6e3c9', NULL, '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-20T09:24:00.0000000', 126), CONVERT(datetime2(3), '2025-10-20T09:24:00.0000000', 126)),
    ('75510d95-1bdf-645d-abdd-0eac436ded70', 'ca37bab4-09c3-f859-b2e5-ca7579b80093', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'我也很有共鳴，尤其是「線上導讀結束後，我最想補看的不是主題作品」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-17T07:36:00.0000000', 126), CONVERT(datetime2(3), '2026-01-17T07:36:00.0000000', 126)),
    ('0aea5fc5-0de5-5550-bc72-0eb4d647d513', '7ecaf2c0-5ed4-4354-a7e1-691cb80d7ffa', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'我也很有共鳴，尤其是「昨晚鑑定遊戲那題，我太早被一個顏色帶走了」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-28T10:39:00.0000000', 126), CONVERT(datetime2(3), '2026-01-28T10:39:00.0000000', 126)),
    ('08951fdd-4cbb-4fc6-85a9-0f8c78bb82dd', '93c6eadf-5ef7-460e-9dd8-f89723e2b911', NULL, '5d5ef6cb-7ee7-4ed0-ad20-7b42e666af70', N'我在整理自己的筆記時會保留原始用詞，再加一欄比較容易理解的說明。這樣既不會改動來源內容，也能讓之後閱讀的人快速知道我當時看見了什麼。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-30T22:14:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('f020f348-024c-395b-8c99-0fed1e4adcf1', '3c55a2f5-2496-c85d-a942-7d37701ce229', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'讀完後我會想再找不同角度的影像來對照。銅胎畫琺瑯芙蓉紋圓盒這類作品如果只看縮圖，真的很容易漏掉邊緣與接合處的線索。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-13T11:47:00.0000000', 126), CONVERT(datetime2(3), '2026-06-13T11:47:00.0000000', 126)),
    ('85727443-c740-d958-a029-0ff7c531ee02', '42b8ac79-4156-055f-9310-8e2e63ce8a43', '977881b5-733e-7557-bd69-6a3b6751a1bc', '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-10T00:46:00.0000000', 126), CONVERT(datetime2(3), '2026-03-10T00:46:00.0000000', 126)),
    ('e7c09dca-e6ef-4105-806a-106ae101a6ec', '2c4b2c95-267f-4563-9e54-836b678311cd', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'我也會先看器形的轉折，再回頭對照紋飾位置。把兩個觀察分開記錄之後，確實比較不容易因為熟悉的圖案就直接聯想到某個年代。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T07:35:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('dfd76b37-db64-c05e-bf81-107bc916d406', '4954163f-6ba6-745b-81dd-d6dfc64f27de', NULL, 'f43ee0b6-a28d-47c1-a5e2-32fa9060383c', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-04T01:50:00.0000000', 126), CONVERT(datetime2(3), '2026-02-04T01:50:00.0000000', 126)),
    ('923b6700-7704-9e5a-99a8-10a62f5f4a32', '178f5461-211c-bb57-8cec-de3143601048', '72d9aadf-a300-6b5e-8fdf-262ab42abfdf', '2d049534-161d-4862-971f-e410d2ac9162', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-17T05:53:00.0000000', 126), CONVERT(datetime2(3), '2026-07-17T05:53:00.0000000', 126)),
    ('8cd32187-5c0f-4256-a700-10f29a798ab4', '21d7be2a-4a81-265a-b6d7-9682411f71b8', '2d8d17ec-ddf3-d555-9cd4-f20fb7f08904', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-03T04:53:00.0000000', 126), CONVERT(datetime2(3), '2026-04-03T04:53:00.0000000', 126)),
    ('1cad355b-d508-105d-be65-111df37a76a5', '2ceb079e-c635-795e-9936-e8ddf550dff0', 'e8f5ba4c-2d44-5656-bd7d-2ee44d7fe230', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-20T02:47:00.0000000', 126), CONVERT(datetime2(3), '2026-07-20T02:47:00.0000000', 126)),
    ('e0926425-98e5-da50-89fb-119e44db7f3d', '7d09817b-6f46-0d53-87d8-ca866a3bc7f8', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-23T01:52:00.0000000', 126), CONVERT(datetime2(3), '2026-07-23T01:52:00.0000000', 126)),
    ('17618d91-23a1-4047-aaa8-11aaaf69a6bc', '109b7d4c-4563-4457-b5f0-91f7cbaf7d34', NULL, 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'我會把這個細節放大後和完整器物照片並排，避免局部看得太清楚反而失去比例。尤其是小件作品，邊緣的一點變化在全圖裡可能完全不同。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T06:27:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('41e50664-42bd-b257-893f-122e889a49bd', '11e0df85-fa91-f950-909a-06fc245383b7', '5fde3bdd-5f36-2755-abed-ebe72ba0da15', '2d049534-161d-4862-971f-e410d2ac9162', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-05T07:55:00.0000000', 126), CONVERT(datetime2(3), '2026-08-05T07:55:00.0000000', 126)),
    ('316e2c4a-0d44-4b5e-8e97-125d8e306a0e', '9bd92ca6-1126-2a5e-9822-d1e3ca15a846', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-14T01:39:00.0000000', 126), CONVERT(datetime2(3), '2025-12-14T01:39:00.0000000', 126)),
    ('edc21b0b-ea75-4a08-8cde-12774eff18c1', 'e4f233f4-2265-4432-ba97-a0991a63a013', NULL, 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這個角度很有幫助，我以前常把照片裡的光影當成表面特徵。若能再補一張側光或器底影像，應該更容易確認目前看到的起伏是不是製作痕跡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-30T21:24:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('22b5d577-9d6f-f753-895f-12fb41975ffa', 'dc987966-47e3-4d52-ad70-78767115ad54', 'eae03bf1-603a-b754-a39b-e5a3383e3eba', '7881ef5d-547d-4d08-b71d-a48be2000a35', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-13T11:48:00.0000000', 126), CONVERT(datetime2(3), '2026-05-13T11:48:00.0000000', 126)),
    ('8d43bb4a-3856-5650-8b53-12fb727349ef', '65fdb4c2-a385-735e-b2e8-cc255a8372f6', 'd170dd93-a5d3-ac54-b87c-4184eee149e0', '9b40d125-cd86-4ee1-9a12-f954c52610fb', N'補充一個小想法：如果之後加入更多照片，可以把拍攝角度和光線條件一起記下來，會更方便比較。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-12T03:48:00.0000000', 126), CONVERT(datetime2(3), '2026-07-12T03:48:00.0000000', 126)),
    ('2c197ccd-207c-4aaa-b6f3-13006fcc1e58', '2d2d7789-caeb-4432-b93d-18809d035fec', NULL, '32090e80-8d61-4801-b480-a6358f7a9e37', N'我之前也遇過來源文字和照片印象不完全一致的情況，後來發現兩者描述的層次不同。先確認每個欄位的用途，再比較內容會清楚很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T02:46:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('4bd5bc8d-646b-4857-85ca-14eaa4b0189b', '8adbfa68-6c2a-8b55-9609-913a69871c22', '07a7acf4-de5b-e552-a449-b79d265227fd', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'如果前台之後提供更多互動，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-30T01:04:00.0000000', 126), CONVERT(datetime2(3), '2026-04-30T01:04:00.0000000', 126)),
    ('02156e5a-1bfe-1e54-8126-15151f3b990a', '17327017-40a5-a95d-902d-9fae2b56af51', '3f442e2b-21a5-5652-9787-04ae29539f29', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-28T08:56:00.0000000', 126), CONVERT(datetime2(3), '2026-07-28T08:56:00.0000000', 126)),
    ('dd1e4caf-58db-417b-8e61-154dbf2fffeb', '073c01a2-fe46-4205-972b-b02523ed147c', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'這個觀察也提醒我不要只依賴單一欄位。年代、分類與來源彼此可以互相校對，但任何一項都不應該脫離完整資料單獨決定答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T01:56:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('cacabcb2-3185-2c57-9ce4-155b88def16d', '024a6fc7-817f-8757-b67e-010526132f0e', 'e752bacd-485e-5f51-aecc-43e6eb19a96f', 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-05T05:51:00.0000000', 126), CONVERT(datetime2(3), '2026-03-05T05:51:00.0000000', 126)),
    ('5100121b-3918-e25c-b0b7-1567a7f33bd7', '43492eba-a671-a550-b712-d4e4d34546c5', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'我也很有共鳴，尤其是「查到新資料時，我會把原本的理解留下來再補更新」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-02T03:45:00.0000000', 126), CONVERT(datetime2(3), '2025-10-02T03:45:00.0000000', 126)),
    ('c98ad510-9f45-2b51-b422-1694944e9058', 'd1b55ecf-c105-f35d-9991-ae616dc52945', NULL, '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-12T05:31:00.0000000', 126), CONVERT(datetime2(3), '2026-01-12T05:31:00.0000000', 126)),
    ('bea5fc83-9e28-215b-ac78-171bead65234', '6ecae0c1-296e-cb58-b721-429c4ffc8ad9', '0135cb91-e2b3-fa57-97e8-4355321bf9b5', 'a1c4407f-acee-4abe-a702-e164fb399b2e', N'我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-18T03:50:00.0000000', 126), CONVERT(datetime2(3), '2026-02-18T03:50:00.0000000', 126)),
    ('84cc18a1-1b26-255c-8a49-1867f4f6e9da', 'eab2d40a-bef9-1f55-859a-07aa6af2ba6e', NULL, 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'我也會先看琉璃珠的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2025-11-20T04:42:00.0000000', 126), CONVERT(datetime2(3), '2025-11-20T04:42:00.0000000', 126)),
    ('63567ba4-1399-4f55-a7a7-18bb1bb3a227', '4e3ae402-37d3-e856-b2d5-c5dd6c5de95d', NULL, '2d049534-161d-4862-971f-e410d2ac9162', N'我也很有共鳴，尤其是「錢幣上的字我看得出來，背後的資料卻還沒讀懂」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-14T07:47:00.0000000', 126), CONVERT(datetime2(3), '2026-04-14T07:47:00.0000000', 126)),
    ('3f349ae1-f641-4d19-9982-195461baeaa8', 'e911d2de-da4a-4557-97e8-80055bcad5ee', NULL, '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'同一個紋樣在平面和曲面上的排列方式不太一樣，轉角位置尤其值得看。若只截取平整區域，可能會錯過製作者如何處理連續圖案的細節。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-31T05:36:25.0750000', 126), CONVERT(datetime2(3), '2026-08-31T08:09:50.8630000', 126)),
    ('77bea40a-1a8f-6259-867b-196c4cf7dbbb', '7b3e8167-2d4c-4e52-aba5-47aa295bd7fe', '07a040be-c52d-b056-990e-8d6d93bcb050', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'這種原則也能幫忙檢查展示資料是否過度延伸；看起來豐富的內容，仍然要讓人知道哪些是原始記錄、哪些是社群整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-17T06:44:00.0000000', 126), CONVERT(datetime2(3), '2026-04-17T06:44:00.0000000', 126)),
    ('d07c4c57-8465-a450-ac57-19a6c3294837', '6f9a89c7-16b8-e355-9b20-97d94f7be8ec', 'be1d6e24-a6df-d153-be2e-8ea252e3e5aa', 'd3964b0b-0c94-4c5a-b925-9bcf806c614e', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-31T00:37:00.0000000', 126), CONVERT(datetime2(3), '2026-05-31T00:37:00.0000000', 126)),
    ('03010f6b-003a-e951-87df-19dff40a63b9', '63cf5b9a-7ff0-1757-8400-8f9bb4584cbd', '055269e2-9ebf-f956-91d4-d7e094a85ddf', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-31T05:39:00.0000000', 126), CONVERT(datetime2(3), '2026-03-31T05:39:00.0000000', 126)),
    ('adbe9f02-5dc0-8856-83db-1a2e07c25fe4', 'b3ac41b8-9d74-4d55-94bf-6f77bb6a12df', NULL, '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'我也很有共鳴，尤其是「沒有看懂不代表沒有收穫，我把卡住的地方留下來了」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-03-29T09:49:00.0000000', 126), CONVERT(datetime2(3), '2026-03-29T09:49:00.0000000', 126)),
