    ('55f3dee9-1080-d359-9fba-05650c7d5d51', N'QMAH-GEN-0051', 'cba35abc-b074-4d30-b5ab-3b793dd62330', NULL, N'FULFILLING', 4980.00, 0.00, 0, 4980.00, N'Demo Store Editor 收', N'0988006987', N'500', N'彰化縣', N'彰化市', N'中山路二段 416 號', CONVERT(datetime2(3), '2026-08-30T18:00:00.0000000', 126), CONVERT(datetime2(3), '2026-08-30T18:05:00.0000000', 126), NULL),
